        "dispatcher.js": function t(e, n, t) {
            var a, i;
            t.link("meteor/meteorflux:dispatcher", {
                Dispatcher: function (t) {
                    a = t
                }
            }, 0),
                t.link("meteor/kadira:flow-router", {
                    FlowRouter: function (t) {
                        i = t
                    }
                }, 1),
                a.register((function (t) {
                    if (t.actionType)
                        switch (t.actionType) {
                            case _HOME:
                            case _SETTING:
                            case _SETPROFILE:
                            case _SETNOTIFICATION:
                            case _SETUSER:
                            case _SETUUID:
                            case _SCANDEVICE:
                            case _SELECTDEVICE:
                            case _SCANDEVICE_FAIL:
                            case _SCANDEVICE_PASS:
                            case _KEYIN_DEVICE:
                            case _SETABOUT:
                            case _ACTIVITY:
                            case _CALYEAR:
                            case _CALMONTH:
                            case _CALWEEK:
                            case _PLANTRIP_MAIN:
                            case _PLANTRIP_CHINA:
                            case _SETSTRAVA:
                            case _SETTP:
                            case _SET_SELFLOOPS:
                            case _SIGNUP:
                            case _WELCOME:
                            case _LOGIN:
                            case _CHANGE_PASSWORD:
                            case _FORGET_PASSWORD:
                            case _FIT_UPLOAD:
                            case _SETPORTRAIT:
                            case BS_BARRINGER.Setting.GridScan:
                            case BS_BARRINGER.Setting.Altitude:
                            case BS_BARRINGER.Setting.Lang:
                            case _WORKOUT:
                                i.go(t.actionType);
                                break;
                            case _TRACKDETAIL:
                                i.go("/trackDetail?id=" + t.id);
                                break;
                            case _SHAREPHOTO:
                                i.go("/sharePhoto?" + t.data);
                                break;
                            case _PLANTRIP_ROUTE:
                                i.go("/plantripRoute?" + t.data);
                                break;
                            case _ISSUE_REPORT:
                                i.go("/issueReport");
                                break;
                            case _BT_UPLOAD:
                                i.go("/btUpload?" + t.data);
                                break;
                            case _BT_SCAN:
                                i.go("/btScan?" + t.data);
                                break;
                            case _BT_PAIR:
                                i.go("/btPair?" + t.data);
                                break;
                            case BS_BARRINGER.Setting.Grid:
                                i.go("/setDevGrid?" + t.data);
                                break;
                            case BS_BARRINGER.Setting.GridMain:
                                i.go("/setDevGridMain?" + t.data);
                                break;
                            case BS_BARRINGER.Setting.CalAltitude:
                                i.go("/calAltitude?" + t.data);
                                break;
                            case "setUnit":
                                bsPref.setUnit(t.unit);
                                break;
                            case "setMap":
                                bsPref.setMap(t.map);
                                break;
                            case "setGoogle":
                                bsPref.setGoogle(t.google);
                                break;
                            case "setUuid":
                                bsPref.setUuid(t.uuid)
                        }
                }
                ))
        },
